[{"category":"section","location":"goesr/#Geostationary-Operational-Environmental-Satellites-(GOES)","page":"GOES-R Example","text":"Example for reading and plotting GOES-R data","title":"Geostationary Operational Environmental Satellites (GOES)"},{"category":"section","location":"goesr/#Basic-Usage","page":"GOES-R Example","text":"using SpaceWeather\nusing SpaceWeather.GOES\nusing Dates\n\n# Download and load XRS data for a single day\nxrs = GOES.XRS[id = 16](Date(2020, 6, 1), Date(2020, 6, 2))\n\n# Access X-ray flux data\nxrsa = xrs[\"xrsa_flux\"]  # Short wavelength (0.05-0.4 nm)\nxrsb = xrs[\"xrsb_flux\"]  # Long wavelength (0.1-0.8 nm)\n\n# load Magnetospheric Particle Sensor High (MPS-HI)\nmpsh_ds = GOES.MPSH[id = 16](Date(2020, 6, 1), Date(2020, 6, 2))\nmpsh_ds[\"AvgDiffProtonFlux\"]\n\n# load MAG Data\nmag_ds = GOES.MAG[id = 16](Date(2020, 6, 1), Date(2020, 6, 2))\nmag_ds[\"b_total\"]","title":"Basic Usage"},{"category":"section","location":"goesr/#Plotting-GOES-R-XRS-Data","page":"GOES-R Example","text":"using CairoMakie\n\nf = Figure()\nax1 = Axis(f[1, 1]; yscale = log10, xlabel = \"Time (UTC)\", ylabel = \"X-Ray Flux\\n($(xrsa.attrib[\"units\"]))\")\ntimes = nomissing(xrs[\"time\"][:])\nlines!(ax1, times, nomissing(xrsa[:]); label = \"GOES-16 XRS-A (0.05-0.4 nm)\", color = :mediumorchid)\nlines!(ax1, times, nomissing(xrsb[:]); label = \"GOES-16 XRS-B (0.1-0.8 nm)\", color = :green)\n\n# Plot 1 day of MPSH 1-minute AvgDiffProtonFlux in Telescope 0, Band 0\nvar = mpsh_ds[\"AvgDiffProtonFlux\"]\nax2 = Axis(f[2, 1]; yscale = log10, xlabel = \"Time (UTC)\", ylabel = \"AvgDiffProtonFlux\\n($(var.attrib[\"units\"]))\")\ntimes = nomissing(mpsh_ds[\"time\"][:])\nlines!(ax2, times, var[1, 1, :])\n\nvar = mag_ds[\"b_total\"]\nax3 = Axis(f[3, 1]; ylabel = \"b_total\\n($(var.attrib[\"units\"]))\")\ntimes = nomissing(mag_ds[\"time\"][:])\nlines!(ax3, times, var[:])\n\nhidexdecorations!.((ax1, ax2); grid = false)\nf","title":"Plotting GOES-R XRS Data"},{"category":"section","location":"#SpaceWeather","page":"Home","text":"(Image: version)\n\nSpaceWeather.jl provides easy access to space weather indices and data, with automatic downloading and caching from various sources.","title":"SpaceWeather"},{"category":"section","location":"#Installation","page":"Home","text":"using Pkg\nPkg.add(\"SpaceWeather\")","title":"Installation"},{"category":"section","location":"#Quickstart","page":"Home","text":"","title":"Quickstart"},{"category":"section","location":"#Basic-Usage","page":"Home","text":"using SpaceWeather\nusing Dates\n\n# Fetch all available space weather data from Celestrak\ndata = celestrak()\n\n# Access Kp index (3-hourly planetary K-index)\nkp_values = data.Kp                              # All Kp values as KeyedArray\nkp_at_time = data.Kp(DateTime(2023, 1, 1, 1, 30))  # Query specific time\n\n# Access Ap index (3-hourly planetary A-index)\nap_values = data.Ap\n\n# Get data for a specific time range\ndata_2023 = celestrak(Date(2023, 1, 1), Date(2023, 12, 31))\nkp_2023 = data_2023.Kp\nap_2023 = data_2023.Ap\n\n# High-level accessor functions\nkp = Kp(Date(2023, 1, 1), Date(2023, 12, 31))\nap = Ap(Date(2023, 1, 1), Date(2023, 12, 31))\n\nData is automatically cached and can be refreshed with celestrak(update=true). Cache is automatically refreshed if older than 30 days.","title":"Basic Usage"},{"category":"section","location":"#API-Reference","page":"Home","text":"","title":"API Reference"},{"category":"type","location":"#SpaceWeather.Celestrak","page":"Home","text":"Celestrak space weather data.\n\nSource: https://celestrak.org/SpaceData/\nDocumentation: https://celestrak.org/SpaceData/SpaceWx-format.php\n\nProvides:\n\ndata.Kp: KeyedArray vector of 3-hourly Kp values indexed by timestamps\ndata.Ap: KeyedArray vector of 3-hourly Ap values indexed by timestamps\nAll CSV columns: data.DATE, data.ISN, data.F10_7_OBS, etc.\n\n\n\n\n\n","title":"SpaceWeather.Celestrak"},{"category":"method","location":"#SpaceWeather.Ap-Tuple","page":"Home","text":"Ap(args...; source=:celestrak, kwargs...)\n\nGet Ap index data from source.\n\n\n\n\n\n","title":"SpaceWeather.Ap"},{"category":"method","location":"#SpaceWeather.Kp-Tuple{Any, Any}","page":"Home","text":"Kp(t0, t1; source=:celestrak, kwargs...)\n\nGet Planetary K-index data from source.\n\nhttps://www.swpc.noaa.gov/products/planetary-k-index\n\n\n\n\n\n","title":"SpaceWeather.Kp"},{"category":"method","location":"#SpaceWeather.celestrak-Tuple{Any, Any}","page":"Home","text":"celestrak(t0, t1; update=false) :: Celestrak\n\nLoad and filter Celestrak data between dates t0 and t1 (inclusive).\n\nExample\n\n# Get data for year 2023\ndata_2023 = celestrak(Date(2023,1,1), Date(2023,12,31))\n\n\n\n\n\n","title":"SpaceWeather.celestrak"},{"category":"method","location":"#SpaceWeather.celestrak-Tuple{}","page":"Home","text":"celestrak(; update=false) :: Celestrak\n\nLoad daily space weather data from Celestrak.\n\nSet update=true to refresh data from the server.\n\nExample\n\ndata = celestrak()\ndata.Kp                           # KeyedArray with 3h timestamps\ndata.Kp(DateTime(2023,1,1,1,30))  # Access by timestamp\ndata.KP1                          # First 3h interval (daily)\ndata.ISN                          # Sunspot numbers\n\n\n\n\n\n","title":"SpaceWeather.celestrak"},{"category":"method","location":"#SpaceWeather.xrsa-Tuple{Any, Any}","page":"Home","text":"xrsa(t0, t1; id=16, kwargs...) :: KeyedArray\n\nGet GOES-R XRS-A (0.05-0.4 nm) X-ray flux data.\n\n\n\n\n\n","title":"SpaceWeather.xrsa"},{"category":"method","location":"#SpaceWeather.xrsb-Tuple{Any, Any}","page":"Home","text":"xrsb(t0, t1; id=16, kwargs...) :: KeyedArray\n\nGet GOES-R XRS-B (0.1-0.8 nm) X-ray flux data.\n\n\n\n\n\n","title":"SpaceWeather.xrsb"},{"category":"module","location":"#SpaceWeather.GOES","page":"Home","text":"Geostationary Operational Environmental Satellites\n\nR Series | NOAA/NASA: https://www.goes-r.gov/\nData Source: https://data.ngdc.noaa.gov/platforms/solar-space-observing-satellites/goes/\nDocumentation: https://www.ngdc.noaa.gov/stp/satellite/goes-r.html\nCatalog: https://catalog.data.gov/dataset/geostationary-operational-environmental-satellite-r-series-goes-r-space-environment-in-situ-sui2\nSEISS Documentation: https://www.ncei.noaa.gov/products/goes-r-space-environment-in-situ\n\n\n\n\n\n","title":"SpaceWeather.GOES"},{"category":"constant","location":"#SpaceWeather.GOES.MAG","page":"Home","text":"Magnetometer (MAG)\n\n\n\n\n\n","title":"SpaceWeather.GOES.MAG"},{"category":"constant","location":"#SpaceWeather.GOES.MPSH","page":"Home","text":"Magnetospheric Particle Sensor High (MPS-HI)\n\n\n\n\n\n","title":"SpaceWeather.GOES.MPSH"},{"category":"constant","location":"#SpaceWeather.GOES.SGPS","page":"Home","text":"Solar and Galactic Proton Sensor (SGPS)\n\n\n\n\n\n","title":"SpaceWeather.GOES.SGPS"},{"category":"constant","location":"#SpaceWeather.GOES.XRS","page":"Home","text":"X-Ray Sensor (XRS)\n\nGOES X-ray plots\n\ngetdata(XRS[id = 16], Date(2020, 6, 1), Date(2020, 6, 3))[\"xrsa_flux\"]\n\n\n\n\n\n","title":"SpaceWeather.GOES.XRS"}]
